// ***************
// Filename: axis_dma_top.sv
// Author: FPGA Cores 4 U
// Description: axis_dma with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map axis_dma_regs
//   (u_regs, src/include/axis_dma_regs.sv, ID "ADMA", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic axis_dma (u_core,
//   src/axis_dma.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   axis_dma_regs.json and the ports of axis_dma: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module axis_dma_top #(
  parameter int MAX_BURST = 16,
  parameter int FIFO_DEPTH = 64
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  output logic [31:0] m_axi_awaddr,
  output logic [7:0]  m_axi_awlen,
  output logic [2:0]  m_axi_awsize,
  output logic [1:0]  m_axi_awburst,
  output logic        m_axi_awvalid,
  input  logic        m_axi_awready,
  output logic [31:0] m_axi_wdata,
  output logic [3:0]  m_axi_wstrb,
  output logic        m_axi_wlast,
  output logic        m_axi_wvalid,
  input  logic        m_axi_wready,
  input  logic [1:0]  m_axi_bresp,
  input  logic        m_axi_bvalid,
  output logic        m_axi_bready,
  output logic [31:0] m_axi_araddr,
  output logic [7:0]  m_axi_arlen,
  output logic [2:0]  m_axi_arsize,
  output logic [1:0]  m_axi_arburst,
  output logic        m_axi_arvalid,
  input  logic        m_axi_arready,
  input  logic [31:0] m_axi_rdata,
  input  logic [1:0]  m_axi_rresp,
  input  logic        m_axi_rlast,
  input  logic        m_axi_rvalid,
  output logic        m_axi_rready,
  output logic [31:0] m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast,
  input  logic [31:0] s_axis_tdata,
  input  logic        s_axis_tvalid,
  output logic        s_axis_tready,
  input  logic        s_axis_tlast,
  output logic        irq_o
);
  // register ports between the register map and the logic
  logic [2:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [31:0] cfg_mm2s_addr;
  logic [31:0] cfg_mm2s_len;
  logic [31:0] cfg_s2mm_addr;
  logic [31:0] cfg_s2mm_len;
  logic [11:0] cfg_status;
  logic cfg_status_wr;
  logic [11:0] sts_status;

  axis_dma_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(cfg_ctrl_wr),
    .mm2s_addr_o(cfg_mm2s_addr),
    .mm2s_addr_wr_o(),
    .mm2s_len_o(cfg_mm2s_len),
    .mm2s_len_wr_o(),
    .s2mm_addr_o(cfg_s2mm_addr),
    .s2mm_addr_wr_o(),
    .s2mm_len_o(cfg_s2mm_len),
    .s2mm_len_wr_o(),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status)
  );
  axis_dma #(
    .MAX_BURST(MAX_BURST),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .m_axi_awaddr,
    .m_axi_awlen,
    .m_axi_awsize,
    .m_axi_awburst,
    .m_axi_awvalid,
    .m_axi_awready,
    .m_axi_wdata,
    .m_axi_wstrb,
    .m_axi_wlast,
    .m_axi_wvalid,
    .m_axi_wready,
    .m_axi_bresp,
    .m_axi_bvalid,
    .m_axi_bready,
    .m_axi_araddr,
    .m_axi_arlen,
    .m_axi_arsize,
    .m_axi_arburst,
    .m_axi_arvalid,
    .m_axi_arready,
    .m_axi_rdata,
    .m_axi_rresp,
    .m_axi_rlast,
    .m_axi_rvalid,
    .m_axi_rready,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .s_axis_tlast,
    .irq_o,
    .cfg_ctrl,
    .cfg_ctrl_wr,
    .cfg_mm2s_addr,
    .cfg_mm2s_len,
    .cfg_s2mm_addr,
    .cfg_s2mm_len,
    .cfg_status,
    .cfg_status_wr,
    .sts_status
  );
endmodule
